    }

    // Exit the program
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for pin 1
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("Error getting GPIO line 1");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for pin 2
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("Error requesting GPIO line 1 as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 1
        gpiod_line_set_value(line1, 1);
        printf("GPIO %d: HIGH\n", GPIO_PIN_1);
        usleep(100000); // 0.1 seconds

        // Toggle GPIO 2
        gpiod_line_set_value(line2, 0);
        printf("GPIO %d: LOW\n", GPIO_PIN_2);
        usleep(100000); // 0.1 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 2
#define GPIO_NUMBER 2

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int result;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 2 as an output */
    gpioSetMode(GPIO_NUMBER, PI_OUTPUT);

    printf("GPIO %d set as output. Press Ctrl+C to exit.\n", GPIO_NUMBER);

    while (!terminate) {
        /* Set GPIO 2 HIGH */
        result = gpioWrite(GPIO_NUMBER, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing HIGH to GPIO %d: %d\n", GPIO_NUMBER, result);
            gpioTerminate();
            return 1;
        }

        /* Wait for 5 seconds */
        sleep(5);

        /* Set GPIO 2 LOW */
        result = gpioWrite(GPIO_NUMBER, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing LOW to GPIO %d: %d\n", GPIO_NUMBER, result);
            gpioTerminate();
            return 1;
        }

        /* Report the state */
        printf("GPIO %d is LOW\n", GPIO_NUMBER);
    }

    /* Terminate pigpio */
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_DIFF_0_1 0x4000 // AIN0 - GND
#define CONFIG_PGA_4_096V 0x0060  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program.\n");
    close(i2c_fd);
    exit(0);
}

// Function to read from the ADS1115
int read_ads1115(int fd, int16_t *raw_value) {
    uint8_t buf[2];
    uint8_t config[3];

    // Build the configuration register value
    config[0] = CONFIG_OS_SINGLE | CONFIG_MUX_DIFF_0_1 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;
    config[1] = 0x00; // Dummy byte
    config[2] = 0x00; // Dummy byte

    // Write the configuration register
    if (write(fd, config, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion register
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *raw_value = (int16_t)((buf[0] << 8) | buf[1]);

    return 0;
}

int main() {
    int16_t raw_value;
    float voltage;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value
        if (read_ads1115(i2c_fd, &raw_value) == 0) {
            // Convert the raw value to voltage
            voltage = (float)raw_value * 4.096 / 32768.0;

            // Print the voltage
            printf("Voltage: %.3f V\n", voltage);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        // Wait 0.5 seconds
        sleep(0.5);
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
