#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define TOBJ1_REG 0x07

int i2c_fd;

void signal_handler(int sig);
int read_mlx90614(int fd, float *temperature, float *ambient_temperature);

int main() {
    float temperature, ambient_temperature;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_mlx90614(i2c_fd, &temperature, &ambient_temperature) == 0) {
            printf("Temperature: %.2f °C, Ambient: %.2f °C\n", temperature, ambient_temperature);
        } else {
            fprintf(stderr, "Error reading MLX90614 data\n");
        }
        sleep(5);
    }

    return 0;
}

void signal_handler(int sig) {
    printf("Ctrl+C pressed, exiting...\n");
    close(i2c_fd);
    exit(0);
}

int read_mlx90614(int fd, float *temperature, float *ambient_temperature) {
    unsigned char buf[4];
    int16_t raw_temp, raw_ambient;

    // Read temperature and ambient temperature registers
    if (read(fd, buf, 4) != 4) {
        perror("Error reading from I2C device");
        return -1;
    }

    raw_temp = (buf[1] << 8) | buf[0];
    raw_ambient = (buf[3] << 8) | buf[2];

    // Convert to Celsius (datasheet formula)
    *temperature = (float)raw_temp * 0.02 - 273.15;
    *ambient_temperature = (float)raw_ambient * 0.02 - 273.15;

    return 0;
}

