#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define timeout in microseconds
#define TIMEOUT 1000000 // 1 second

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long measurePulseWidth() {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin did not go high within timeout.\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin did not go low within timeout.\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    return (pulseWidth / 2.0) / 29.1;
}

// Function to report the distance to standard output
void reportDistance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stdout, "HC-SR04 sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
