        /* Toggle GPIO state */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
            break;
        }

        /* Report the state */
        printf("GPIO %d is LOW\n", GPIO_PIN);

        /* Wait for 1 second */
        sleep(1);
    }

