#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40

// Function to read temperature from SI7021
float read_temperature(int fd) {
    unsigned char buf[2];
    int result;

    buf[0] = 0xE3; // Command to measure temperature
    result = write(fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    usleep(100000); // Wait for measurement (100ms)

    result = read(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    return temperature;
}

// Function to read humidity from SI7021
float read_humidity(int fd) {
    unsigned char buf[2];
    int result;

    buf[0] = 0xE5; // Command to measure humidity
    result = write(fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    usleep(100000); // Wait for measurement (100ms)

    result = read(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    return humidity;
}

int main() {
    int fd;
    float temperature, humidity;

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        temperature = read_temperature(fd);
        humidity = read_humidity(fd);

        if (temperature > -999.0 && humidity > -999.0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(5);
    }

    // Close I2C bus (this will never be reached in the current loop)
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int main() {
    int file;
    int16_t reading;
    char buf[2];

    file = open(I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, +/-4.096V, 128 SPS
    buf[0] = CONFIG_REG;
    buf[1] = 0x44; // Single-ended A0, +/-4.096V, 128 SPS, Start single conversion
    if (write(file, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    buf[0] = CONVERSION_REG;
    if (write(file, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    if (read(file, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        close(file);
        return 1;
    }

    reading = (buf[0] << 8) | buf[1];

    // Calculate voltage
    float voltage = (reading * REF_VOLTAGE) / 32768.0;

    printf("ADS1115 Reading: %.3f V\n", voltage);

    close(file);
    return 0;
}

