    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    for (int i = 0; i < 7; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Release chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit the program
    exit(0);
}

