    lines[0] = gpiod_chip_get_line(chip, GPIO_8);
    lines[1] = gpiod_chip_get_line(chip, GPIO_9);
    lines[2] = gpiod_chip_get_line(chip, GPIO_10);
    lines[3] = gpiod_chip_get_line(chip, GPIO_11);
    lines[4] = gpiod_chip_get_line(chip, GPIO_23);
    lines[5] = gpiod_chip_get_line(chip, GPIO_24);
    lines[6] = NULL; // Add a null terminator

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3] || !lines[4] || !lines[5]) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines as output
    for (int i = 0; i < 7; i++) {
        if (lines[i]) {
            if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
                perror("Error requesting GPIO line as output");
                gpiod_chip_close(chip);
                return -1;
            }
        }
    }

    return 0;
}

// Function to cycle GPIO lines
void cycle_gpio(void) {
    for (int i = 0; i < 7; i++) {
        if (lines[i]) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("Error setting GPIO value to 1");
            } else {
                printf("GPIO %d set to 1\n", lines[i]->line);
            }
            usleep(100000); // 100ms

            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("Error setting GPIO value to 0");
            } else {
                printf("GPIO %d set to 0\n", lines[i]->line);
            }
            usleep(100000); // 100ms
        }
    }
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup_gpio);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    // Run the GPIO control loop
    for (int i = 0; i < NUM_CYCLES; i++) {
        cycle_gpio();
    }

    // Cleanup and exit
    cleanup_gpio(0);

