#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define timeout in microseconds
#define TIMEOUT 1000000 // 1 second

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the pulse width on the echo pin
long measurePulseWidth() {
    long startTime = 0, endTime = 0;
    long pulseWidth = -1; // Initialize to an invalid value

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin did not go high within timeout.\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin did not go low within timeout.\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    // Calculate the pulse width in microseconds
    pulseWidth = endTime - startTime;
    return pulseWidth;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (float)pulseWidth * 0.0343 / 2.0;
}

// Function to report the distance
void reportDistance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulseWidth = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Report the distance
        reportDistance(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

