#define DHT11_GPIO 4
#define MAX_TIMINGS 85

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht11(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;
    long startTime, endTime;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30 microseconds
    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT11 to pull the line low (response signal)
    startTime = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - startTime > 100000) { // Timeout after 100ms
            fprintf(stderr, "DHT11: Timeout waiting for response\n");
            return -1;
        }
    }

    // Read the 40 bits of data
    for (i = 0; i < MAX_TIMINGS; i++) {
        startTime = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - startTime > 100000) { // Timeout after 100ms
                fprintf(stderr, "DHT11: Timeout waiting for bit start\n");
                return -1;
            }
        }

        startTime = gpioTick();
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - startTime > 100000) { // Timeout after 100ms
                fprintf(stderr, "DHT11: Timeout waiting for bit end\n");
                return -1;
            }
        }

        endTime = gpioTick();
        if (endTime - startTime > 40) {
            data[bit_count] |= (1 << (7 - bit_count));
        }
        bit_count++;

        if (bit_count == 40) break;
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT11: Checksum error\n");
        return -1;
    }

    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result = read_dht11(DHT11_GPIO, &temperature, &humidity);

    if (result == 0) {
        printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "DHT11 read failed\n");
        gpioTerminate();
        return 1;
    }

    gpioTerminate();
    return 0;
}

