    // Read Result Register (0x00)
    uint8_t result_reg = 0x00;
    if (write(fd, &result_reg, 1) != 1) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    uint8_t result[2];
    if (read(fd, result, 2) != 2) {
        perror("Failed to read from I2C device");
        close(fd);
        return 1;
    }

    uint16_t raw_value = (result[0] << 8) | result[1];
    float voltage = raw_value * 4.096 / 2047.0;
    printf("OPT3001 Reading: %.2f V\n", voltage);

    close(fd);
    return 0;
}

