#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define MAX_BUFFER_SIZE 256
#define TIMEOUT_SEC 5

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 1; // 0.1 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, int buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return 0;
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART setup failed. Exiting.\n");
        return 1;
    }

    char buffer[MAX_BUFFER_SIZE];
    time_t start_time = time(NULL);

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, buffer, MAX_BUFFER_SIZE);
        if (bytes_read > 0) {
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }

        time_t current_time = time(NULL);
        if (difftime(current_time, start_time) > TIMEOUT_SEC) {
            fprintf(stderr, "Timeout: No data received for %d seconds. Exiting.\n", TIMEOUT_SEC);
            break;
        }
    }

    close(uart_fd);
    printf("UART port closed.\n");

    return 0;
}

