    result = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(GPIO_PIN_ALT, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", GPIO_PIN_ALT, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Main loop */
    while (!terminate) {
        /* Toggle GPIO 2 */
        result = gpioWrite(GPIO_PIN, 1);
        if (result != 0) {
            fprintf(stderr, "Failed to write to GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            gpioTerminate();
            return 1;
        }

        /* Toggle GPIO 3 */
        result = gpioWrite(GPIO_PIN_ALT, 0);
        if (result != 0) {
            fprintf(stderr, "Failed to write to GPIO %d: %s\n", GPIO_PIN_ALT, strerror(errno));
            gpioTerminate();
            return 1;
        }

        /* Print the state of GPIO 2 */
        printf("GPIO %d: %d\n", GPIO_PIN, gpioRead(GPIO_PIN));

        /* Wait 0.1 seconds */
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    /* Terminate pigpio */
    gpioTerminate();

    return 0;
}

