#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"
#define MAX_TEMP_STR_LEN 20

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to discover DS18B20 devices
int discover_ds18b20_devices(char device_ids[][20]) {
    DIR *d;
    struct dirent *dir;
    int device_count = 0;

    d = opendir(W1_DEVICES_DIR);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            if (strncmp(dir->d_name, "28-", 3) == 0) {
                if (device_count < 10) {
                    strncpy(device_ids[device_count], dir->d_name, sizeof(device_ids[device_count]) - 1);
                    device_ids[device_count][sizeof(device_ids[device_count]) - 1] = '\0'; // Ensure null termination
                    device_count++;
                } else {
                    fprintf(stderr, "Warning: More than 10 DS18B20 devices found.  Only the first 10 will be used.\n");
                    break;
                }
            }
        }
        closedir(d);
    } else {
        perror("Error opening " W1_DEVICES_DIR);
        return -1;
    }
    return device_count;
}

// Function to read temperature from a DS18B20 device
float read_temperature(const char *device_id) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s/%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        perror("Error opening w1_slave file");
        return -1000.0; // Indicate error
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        perror("Error reading w1_slave file");
        return -1000.0; // Indicate error
    }
    buffer[bytes_read] = '\0';

    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in w1_slave file.\n");
        return -1000.0; // Indicate error
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    return (float)temp_raw / 1000.0;
}

// Function to validate temperature reading
int validate_temperature(float temperature) {
    if (temperature < -50.0 || temperature > 100.0) {
        fprintf(stderr, "Error: Temperature reading out of range: %.2f\n", temperature);
        return 0; // Invalid
    }
    return 1; // Valid
}

int main() {
    char device_ids[10][20];
    int num_devices;

    signal(SIGINT, signal_handler);

    num_devices = discover_ds18b20_devices(device_ids);
    if (num_devices < 0) {
        fprintf(stderr, "Error discovering DS18B20 devices. Exiting.\n");
        return 1;
    }

    printf("Found %d DS18B20 devices.\n", num_devices);

    while (program_running) {
        for (int i = 0; i < num_devices; i++) {
            float temperature = read_temperature(device_ids[i]);
            if (temperature > -999.0) { // Check for read error
                if (validate_temperature(temperature)) {
                    printf("Device ID: %s, Temperature: %.2f °C\n", device_ids[i], temperature);
                }
            }
        }
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void int_handler(int dummy) {
    keep_running = 0;
}

int read_htu21d(int fd, float *temperature, float *humidity) {
    uint8_t buf[4];
    uint16_t raw_temperature, raw_humidity;
    int result;

    // Request temperature measurement
    buf[0] = 0xE3; // Command register
    buf[1] = 0x00; // Temperature measurement command
    result = write(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }
    usleep(50000); // Wait 50ms

    // Read temperature data
    result = read(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    raw_temperature = (buf[0] << 8) | buf[1];

    // Request humidity measurement
    buf[0] = 0xE5; // Command register
    buf[1] = 0x00; // Humidity measurement command
    result = write(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing humidity command: %s\n", strerror(errno));
        return -1;
    }
    usleep(50000); // Wait 50ms

    // Read humidity data
    result = read(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
        return -1;
    }
    raw_humidity = (buf[0] << 8) | buf[1];

    // Convert raw data to temperature and humidity
    *temperature = -46.85 + 175.72 * (float)raw_temperature / 65536.0;
    *humidity = -6.0 + 125.0 * (float)raw_humidity / 65536.0;

    // Validate readings
    if (*temperature < -40.0 || *temperature > 125.0 || *humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Invalid sensor readings: Temperature=%.2f, Humidity=%.2f\n", *temperature, *humidity);
        return -1;
    }

    return 0;
}

int main() {
    float temperature, humidity;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    signal(SIGINT, int_handler);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
