#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the ADXL345
int adxl345_init(int fd) {
    // Set POWER_CTL register to measure mode
    if (i2c_smbus_write_byte_data(fd, POWER_CTL, 0x08) < 0) {
        perror("Error writing to POWER_CTL register");
        return -1;
    }

    // Set DATA_FORMAT register to +/- 2g range and full resolution
    if (i2c_smbus_write_byte_data(fd, DATA_FORMAT, 0x0B) < 0) {
        perror("Error writing to DATA_FORMAT register");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Read 6 bytes of data starting from DATAX0
    if (read(fd, data, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    // Combine the bytes to form 16-bit signed integers
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;

    // Main loop
    while (1) {
        // Read acceleration data
        if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Print the acceleration values
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // The program should never reach here, but include cleanup for safety
    close(i2c_fd);
    return 0;
}

