// Define GPIO pins for DHT22 data and clock
#define DHT22_DATA_PIN 17
#define DHT22_CLOCK_PIN 22
#define DHT22_STRETCH_PIN 23
#define DHT22_POWER_PIN 24

// Define constants for DHT22 communication
#define DHT22_READ_COMMAND 0x00
#define DHT22_READ_LENGTH 8

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read data from DHT22 sensor
int read_dht22(float *temperature, float *humidity)
{
    int data[DHT22_READ_LENGTH] = {0};
    int bit_count = 0;
    int i, j;

    // Send start signal
    gpioWrite(DHT22_POWER_PIN, 1);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_POWER_PIN, 0);
    gpioDelay(18); // 18ms

    // Send read command
    gpioWrite(DHT22_CLOCK_PIN, 0);
    gpioDelay(1); // 1us
    gpioWrite(DHT22_CLOCK_PIN, 1);
    gpioDelay(30); // 30us

    // Read data
    for (i = 0; i < DHT22_READ_LENGTH; i++)
    {
        // Wait for data pin to go low
        while (gpioRead(DHT22_DATA_PIN) == 1)
        {
            gpioDelay(1); // Wait 1us
        }

        // Wait for data pin to go high
        while (gpioRead(DHT22_DATA_PIN) == 0)
        {
            gpioDelay(1); // Wait 1us
        }

        // Determine if bit is 0 or 1 based on clock pulse duration
        for (j = 0; j < 3; j++)
        {
            gpioWrite(DHT22_CLOCK_PIN, 0);
            gpioDelay(1); // 1us
            if (gpioRead(DHT22_DATA_PIN) == 1)
            {
                data[i] |= (1 << (2 - j));
            }
            gpioWrite(DHT22_CLOCK_PIN, 1);
            gpioDelay(1); // 1us
        }
    }

    // Checksum validation
    if ((data[0] + data[1] + data[2] + data[3]) != data[4])
    {
        fprintf(stderr, "Checksum error\n");
        return -1; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) | data[3])) / 10.0;
    if (*temperature > 125)
    {
        *temperature = *temperature - 256;
    }

    return 0; // Success
}

int main()
{
    float temperature, humidity;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(DHT22_DATA_PIN, PI_INPUT);
    gpioSetMode(DHT22_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(DHT22_STRETCH_PIN, PI_INPUT);
    gpioSetMode(DHT22_POWER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        result = read_dht22(&temperature, &humidity);
        if (result == 0)
        {
            printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", temperature, humidity);
