    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d: %d\n", PWM_GPIO, gpio_status);
        gpioTerminate();
        return 1; // Exit with an error code
    }

    gpio_status = gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d: %d\n", PWM_GPIO, gpio_status);
        gpioTerminate();
        return 1; // Exit with an error code
    }

