#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_WTIME           0x03
#define TCS34725_AILTL           0x04
#define TCS34725_AILTH           0x05
#define TCS34725_AIHTL           0x06
#define TCS34725_AIHTH           0x07
#define TCS34725_ID              0x12
#define TCS34725_STATUS          0x13
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A
#define TCS34725_PDATA           0x1C
#define TCS34725_CONTROL         0x0F

// Enable Register Values
#define TCS34725_ENABLE_AIEN     0x10  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN      0x08  // Wait Enable
#define TCS34725_ENABLE_AEN      0x02  // ALS Enable
#define TCS34725_ENABLE_PON      0x01  // Power On

int i2c_fd;
volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int tcs34725_init() {
    // Enable power and ALS
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error: Could not enable device. %s\n", strerror(errno));
        return -1;
    }

    // Set integration time (ATIME) - 2.4ms * 256
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error: Could not set integration time. %s\n", strerror(errno));
        return -1;
    }

    // Set gain (AGAIN) - 4x gain
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error: Could not set gain. %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int tcs34725_read_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    unsigned char data[8];

    // Read all color data registers in one go
    if (read(i2c_fd, data, 8) != 8) {
        fprintf(stderr, "Error: Could not read color data. %s\n", strerror(errno));
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

