#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3)
#define IMAGE_FILE "captured_image.yuv"

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    unsigned char *buffer = NULL;
    FILE *fp = NULL;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // YUYV format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Allocate buffer
    buffer = (unsigned char *)malloc(IMAGE_SIZE);
    if (buffer == NULL) {
        perror("Error allocating buffer");
        close(fd);
        return 1;
    }

    // Capture image
    if (read(fd, buffer, IMAGE_SIZE) < 0) {
        perror("Error reading from device");
        free(buffer);
        close(fd);
        return 1;
    }

    // Save image to file
    fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        free(buffer);
        close(fd);
        return 1;
    }

    size_t bytes_written = fwrite(buffer, 1, IMAGE_SIZE, fp);
    if (bytes_written != IMAGE_SIZE) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, IMAGE_SIZE);
        fclose(fp);
        free(buffer);
        close(fd);
        return 1;
    }

    fclose(fp);
    printf("Image saved to %s\n", IMAGE_FILE);

    // Cleanup
    free(buffer);
    close(fd);

    return 0;
}

