int initialize_gpio(struct gpiod_chip *chip, int gpio) {
    char line_name[3];
    snprintf(line_name, sizeof(line_name), "gpio%d", gpio);
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_name);
    if (!line) {
