#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 23
#define CEILING_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for the echo pin to go high (or timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (or timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to report the distance
void reportDistance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(CEILING_PIN, PI_INPUT);

    // Set pull-down resistor on CEILING_PIN
    gpioSetPullUpDown(CEILING_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Measure the distance
        float distance = measureDistance();

        // Report the distance
        if (distance >= 0) {
            reportDistance(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        // Wait for 0.2 seconds
        gpioDelay(200000); // 200 ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

