    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 1; // Timeout of 1 second
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Copy the image data to the buffer
    memcpy(buffer, buf.bytes, buf.length);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to save the image to a file
int save_image(const unsigned char *buffer, size_t buffer_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file %s: wrote %zu bytes, expected %zu\n", filename, bytes_written, buffer_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

