    if (image_buffer == NULL) {
        fprintf(stderr, "Error allocating memory for image buffer\n");
        close_camera(fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (capture_image(fd, image_buffer, IMAGE_BUFFER_SIZE) == 0) {
