        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 0.05 seconds
        nanosleep(&sleep_time, NULL);
    }

    free(image_buffer);
    close_camera(fd);

    return EXIT_SUCCESS;
}

