int16_t read_i2c_word(int fd, uint8_t reg) {
    int16_t value;
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    value = (buf[0] << 8) | buf[1];
    return value;
}

