// Define the I2C address of the HD44780
#define HD44780_ADDR 0x27

// Define the I2C file descriptor
int i2c_fd;

// Function to initialize the HD44780
int init_hd44780() {
    // Initialization sequence (refer to HD44780 datasheet)
    unsigned char init_sequence[] = {
        0x03, // Function set: 8-bit mode
        0x03, // Function set: 2-line, 5x8 font
        0x03, // Function set: 2-line, 5x8 font
        0x02, // Function set: 2-line, 5x8 font
        0x01  // Clear display
    };

    for (int i = 0; i < sizeof(init_sequence); i++) {
        if (write(i2c_fd, &init_sequence[i], 1) != 1) {
            perror("Error writing to I2C device");
            return -1;
        }
        usleep(1000); // Small delay after each write
    }

    return 0;
}

// Function to display a string on the HD44780
void display_string(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        unsigned char data = str[i];
        if (write(i2c_fd, &data, 1) != 1) {
            perror("Error writing to I2C device");
        }
    }
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nExiting program...\n");
        close(i2c_fd);
        exit(0);
    }
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the HD44780
    if (init_hd44780() != 0) {
        fprintf(stderr, "HD44780 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    char timestamp[20];
    char display_buffer[20];

    while (1) {
        // Get the current timestamp
        get_timestamp(timestamp);

        // Format the display buffer
        snprintf(display_buffer, sizeof(display_buffer), "Time: %s", timestamp);

        // Display the string
        display_string(display_buffer);

        // Wait for 10 seconds
        sleep(10);
    }

    // The program should never reach here, but it's good practice to close the I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    int value = i2c_smbus_read_byte_data(fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_high, x_low, y_high, y_low, z_high, z_low;

    x_high = read_register(fd, ACCEL_XOUT_H);
    x_low = read_register(fd, ACCEL_XOUT_L);
    y_high = read_register(fd, ACCEL_YOUT_H);
    y_low = read_register(fd, ACCEL_YOUT_L);
    z_high = read_register(fd, ACCEL_ZOUT_H);
    z_low = read_register(fd, ACCEL_ZOUT_L);

    if (x_high < 0 || x_low < 0 || y_high < 0 || y_low < 0 || z_high < 0 || z_low < 0) {
        return -1;
    }

    *x = (int16_t)((x_high << 8) | x_low);
    *y = (int16_t)((y_high << 8) | y_low);
    *z = (int16_t)((z_high << 8) | z_low);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (write_register(i2c_fd, PWR_MGMT_1, 0) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Read and print accelerometer data 100 times
    for (int i = 0; i < 100; i++) {
        int16_t x, y, z;

        if (read_accelerometer(i2c_fd, &x, &y, &z) == 0) {
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

