// Configuration
#define MQTT_HOST "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define GPIO_PIN 4 // GPIO pin connected to the sensor
#define READ_INTERVAL_US 10000 // 0.01 seconds

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_sensor();
int validate_reading(int reading);
int publish_mqtt(int reading);
void signal_handler(int signal);
int setup_mqtt();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Reads the sensor value from the specified GPIO pin
int read_sensor() {
    int reading = gpioRead(GPIO_PIN);
    if (reading < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", GPIO_PIN, reading);
        return -1; // Indicate error
    }
    return reading;
}

// Validates the sensor reading
int validate_reading(int reading) {
    if (reading >= 0 && reading <= 1) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Publishes the sensor reading to the MQTT broker
int publish_mqtt(int reading) {
    char payload[2];
    snprintf(payload, sizeof(payload), "%d", reading);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing to MQTT: %s\n", mosquitto_strerror(ret));
        return -1; // Indicate error
    }
    return 0; // Success
}

// Sets up the MQTT client
int setup_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up MQTT
    if (setup_mqtt() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Sensor data publishing started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int reading = read_sensor();
        if (reading >= 0) {
            if (validate_reading(reading)) {
                if (publish_mqtt(reading) == 0) {
                    //printf("Published: %d\n", reading);
                } else {
                    fprintf(stderr, "Failed to publish MQTT message.\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor reading: %d\n", reading);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(READ_INTERVAL_US);
    }

    // Clean up and exit
    cleanup();
    printf("Sensor data publishing stopped.\n");
    return 0;
}

