// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22
#define DISCHARGE_PIN 27

// Define constants
#define TIMEOUT_US 50000 // 50ms timeout
#define MIN_DISTANCE 2.0  // Minimum valid distance (cm)
#define MAX_DISTANCE 400.0 // Maximum valid distance (cm)

// Global variable for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulse() {
    long start_tick, end_tick, pulse_duration;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    if (pulse_duration < 0) {
        pulse_duration += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) return -1.0; // Indicate error
    return (pulse_duration * 0.0343) / 2.0;
}

// Function to validate the distance reading
int validateDistance(float distance) {
    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Function to discharge the capacitor
void dischargeCapacitor() {
    gpioWrite(DISCHARGE_PIN, 1);
    gpioDelay(10); // 10us discharge pulse
    gpioWrite(DISCHARGE_PIN, 0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(DISCHARGE_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(DISCHARGE_PIN, 0);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse duration
        long pulse_duration = measurePulse();

        // Calculate the distance
        float distance = calculateDistance(pulse_duration);

        // Validate the distance
        if (validateDistance(distance)) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance reading\n");
        }

        // Discharge the capacitor
        dischargeCapacitor();

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

