    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Initialize GPIO lines
    if (gpio_2_init() < 0 || gpio_3_init() < 0 || gpio_23_init() < 0) {
        cleanup(0); // Call cleanup before exiting
        return 1;
