#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_HOST "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor/temperature"
#define SENSOR_PIN 4 // GPIO pin connected to the sensor
#define SLEEP_INTERVAL 5 // seconds

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_sensor();
char* format_data(int sensor_value);
int publish_mqtt(const char* data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Reads the sensor value from the specified GPIO pin
int read_sensor() {
    int value = gpioRead(SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Formats the sensor data into a string with a timestamp
char* format_data(int sensor_value) {
    struct timeval tv;
    struct tm* timeinfo;
    char timestamp[30];
    static char data[50]; // Static to persist across calls

    gettimeofday(&tv, NULL);
    timeinfo = localtime(&tv.tv_sec);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(data, sizeof(data), "%s.%06ld, %d", timestamp, tv.tv_usec, sensor_value);

    return data;
}

// Publishes the data to the MQTT broker
int publish_mqtt(const char* data) {
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(data), data, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing MQTT message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor data publishing...\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value >= 0) {
            char* formatted_data = format_data(sensor_value);
            if (publish_mqtt(formatted_data) == 0) {
                printf("Published: %s\n", formatted_data);
            } else {
                fprintf(stderr, "Failed to publish data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(SLEEP_INTERVAL);
    }

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

