#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define timeout duration (in seconds)
#define TIMEOUT_DURATION 0.2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to measure the duration of the echo pulse
long measurePulse() {
    long startTime = 0, endTime = 0;
    long pulseDuration = 0;

    // Wait for the echo pin to go HIGH
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go HIGH within timeout.\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for the echo pin to go LOW
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go LOW within timeout.\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    pulseDuration = endTime - startTime;
    return pulseDuration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    // Speed of sound in air (approx. 343 m/s)
    // Divide by 2 because of the round trip
    return (pulseDuration * 0.0343) / 2.0;
}

// Function to report the distance
void reportDistance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stdout, "HC-SR04 distance sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseDuration = measurePulse();

        if (pulseDuration > 0) {
            float distance = calculateDistance(pulseDuration);
            reportDistance(distance);
        } else {
            fprintf(stderr, "Error: Could not measure pulse duration.\n");
        }

        gpioDelay(100); // Delay for 0.1 seconds (100 milliseconds)
    }

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stdout, "Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_23 23

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm(int gpio, int duty_cycle)
{
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio);
    }
}

// Function to report the state of a GPIO pin
void report_state(int gpio, int state)
{
    printf("GPIO %d: %s\n", gpio, state ? "ON" : "OFF");
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_17, 255);
    gpioSetPWMrange(GPIO_18, 255);
    gpioSetPWMrange(GPIO_22, 255);
    gpioSetPWMrange(GPIO_23, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Turn on GPIO 17
        set_pwm(GPIO_17, 128);
        report_state(GPIO_17, 1);

        // Turn on GPIO 18
        set_pwm(GPIO_18, 128);
        report_state(GPIO_18, 1);

        // Turn on GPIO 22
        set_pwm(GPIO_22, 128);
        report_state(GPIO_22, 1);

        // Turn on GPIO 23
        set_pwm(GPIO_23, 128);
        report_state(GPIO_23, 1);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds

        // Turn off all GPIOs
        set_pwm(GPIO_17, 0);
        set_pwm(GPIO_18, 0);
        set_pwm(GPIO_22, 0);
        set_pwm(GPIO_23, 0);

        // Report the state again
        report_state(GPIO_17, 0);
        report_state(GPIO_18, 0);
        report_state(GPIO_22, 0);
        report_state(GPIO_23, 0);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
