// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TOPIC "home/sensor/temperature"
#define SENSOR_GPIO 4 // GPIO pin connected to the sensor
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_sensor_data(int gpio_pin);
float validate_sensor_data(int raw_value);
int publish_mqtt(float temperature);
void signal_handler(int signal);
int mqtt_connect_and_publish(float temperature);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data from the specified GPIO pin
int read_sensor_data(int gpio_pin) {
    int raw_value = gpioRead(gpio_pin);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, raw_value);
        return -1; // Indicate error
    }
    return raw_value;
}

// Function to validate sensor data
float validate_sensor_data(int raw_value) {
    if (raw_value < 0 || raw_value > 1023) {
        fprintf(stderr, "Invalid sensor data: %d\n", raw_value);
        return -1.0; // Indicate invalid data
    }
    return (float)raw_value;
}

// Function to publish the sensor data to the MQTT broker
int publish_mqtt(float temperature) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing to MQTT: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Function to handle MQTT connection and publishing
int mqtt_connect_and_publish(float temperature) {
    int ret;

    // Connect to MQTT broker
    ret = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    // Publish the temperature reading
    if (publish_mqtt(temperature) != 0) {
        fprintf(stderr, "Error publishing temperature to MQTT.\n");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    // Disconnect from MQTT broker
    ret = mosquitto_disconnect(mosq);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error disconnecting from MQTT broker: %s\n", mosquitto_strerror(ret));
    }

    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Initialize MQTT library
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor data publishing...\n");

    while (running) {
        // Read sensor data
        int raw_value = read_sensor_data(SENSOR_GPIO);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        // Validate sensor data
        float temperature = validate_sensor_data(raw_value);
        if (temperature < 0) {
            fprintf(stderr, "Invalid sensor data, retrying in %d seconds...\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        // Publish to MQTT
        if (mqtt_connect_and_publish(temperature) != 0) {
            fprintf(stderr, "Error publishing to MQTT, retrying in %d seconds...\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        printf("Published temperature: %.2f\n", temperature);

        // Wait for the next reading
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_ads1115_publisher"
#define MQTT_TOPIC "home/sensors/ads1115"
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // +/- 4.096V
#define FULL_SCALE_VOLTAGE 4.096
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mqtt();
int read_ads1115(int channel);
float convert_to_voltage(int16_t raw_value);
int publish_mqtt(float voltage);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize MQTT
int init_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        return -1;
    }

    if (mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60)) {
        fprintf(stderr, "Error connecting to MQTT broker\n");
        mosquitto_destroy(mosq);
        mosq = NULL;
        return -1;
    }

    return 0;
}

// Read from ADS1115
int read_ads1115(int channel) {
    if (channel < 0 || channel > 3) {
        fprintf(stderr, "Invalid ADS1115 channel: %d\n", channel);
        return -1;
    }

    // Configure ADS1115 for single-ended mode and desired channel
    uint16_t config = 0;
    switch (channel) {
        case 0:
            config = 0x4003; // GND, +/- 4.096V, Single-shot mode, 128 SPS
            break;
        case 1:
            config = 0x4203; // AIN0, +/- 4.096V, Single-shot mode, 128 SPS
            break;
        case 2:
            config = 0x4403; // AIN1, +/- 4.096V, Single-shot mode, 128 SPS
            break;
        case 3:
            config = 0x4603; // AIN2, +/- 4.096V, Single-shot mode, 128 SPS
            break;
        default:
            config = 0x4003; // Default to channel 0 if invalid channel
    }

    // Write configuration to ADS1115
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // Wait 10ms

    // Read conversion register
    char read_buf[2];
    if (i2cWriteDevice(i2c_handle, (char[]){CONVERSION_REG}, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for read\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 0) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Convert raw value to voltage
float convert_to_voltage(int16_t raw_value) {
    return ((float)raw_value / 32768.0) * FULL_SCALE_VOLTAGE;
}

// Publish MQTT message
int publish_mqtt(float voltage) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.3f", voltage);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing MQTT message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    for (int i = 0; i < 10 && !terminate; ++i) {
        int16_t raw_value = read_ads1115(0); // Read from channel 0
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADS1115, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

