void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    uint8_t buf[2];
    int result;

    // Wake up the MPU6050 (set sleep bit to 0)
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    result = write(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the MPU6050
int16_t read_mpu6050_word(int fd, uint8_t reg) {
    uint8_t buf[1];
    uint8_t data[2];
    int result;

    buf[0] = reg;
    result = write(fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    result = read(fd, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return (int16_t)((data[0] << 8) | data[1]);
}

