void read_accelerometer(int fd) {
    int16_t accel_x, accel_y, accel_z;
    time_t rawtime;
    struct tm *timeinfo;

    accel_x = read_mpu6050_word(fd, ACCEL_XOUT_H);
    accel_y = read_mpu6050_word(fd, ACCEL_YOUT_H);
    accel_z = read_mpu6050_word(fd, ACCEL_ZOUT_H);

    if (accel_x == -1 || accel_y == -1 || accel_z == -1) {
        fprintf(stderr, "Error reading accelerometer data.\n");
        return;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    printf("%sAccelerometer: X=%6d, Y=%6d, Z=%6d\n", asctime(timeinfo), accel_x, accel_y, accel_z);
}

