        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        read_accelerometer(i2c_fd);
        usleep(100000); // 0.1 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

