        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature and pressure
        if (read_bmp280(i2c_fd, &temperature, &pressure) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print temperature and pressure
            printf("%s - Temperature: %.2f °C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read BMP280 data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define PWM_GPIO 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

int main() {
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    result = gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Main loop: Toggle PWM duty cycle
    while (1) {
        // Set duty cycle to 50% (500)
        result = gpioPWM(PWM_GPIO, PWM_RANGE / 2);
        if (result != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle: %d\n", result);
            gpioTerminate();
            return 1;
        }

        // Report the state
        printf("PWM state: %d\n", result);

        // Wait for 1 second
        sleep(1);

        // Set duty cycle to 0
        result = gpioPWM(PWM_GPIO, 0);
        if (result != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle: %d\n", result);
            gpioTerminate();
            return 1;
        }

        // Report the state
        printf("PWM state: %d\n", result);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library (this will never be reached in the current loop)
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

// Define GPIO chip name (adjust if necessary)
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio_5_line, *gpio_6_line, *gpio_13_line;

// Function prototypes
int gpio_init(void);
int gpio_set_value(int gpio, int value);
int gpio_get_value(int gpio);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (gpio_5_line) {
        gpiod_line_release(gpio_5_line);
    }
    if (gpio_6_line) {
        gpiod_line_release(gpio_6_line);
    }
    if (gpio_13_line) {
        gpiod_line_release(gpio_13_line);
    }

    // Release chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit program
    exit(0);
}

// Initialize GPIO lines
int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_5_line = gpiod_chip_get_line(chip, GPIO_5);
    if (!gpio_5_line) {
        perror("Error getting GPIO 5 line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpio_6_line = gpiod_chip_get_line(chip, GPIO_6);
    if (!gpio_6_line) {
        perror("Error getting GPIO 6 line");
        gpiod_line_release(gpio_5_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpio_13_line = gpiod_chip_get_line(chip, GPIO_13);
    if (!gpio_13_line) {
        perror("Error getting GPIO 13 line");
        gpiod_line_release(gpio_5_line);
        gpiod_line_release(gpio_6_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_5_line, "gpio_5", 0) < 0) {
        perror("Error requesting GPIO 5 as output");
        gpiod_line_release(gpio_5_line);
        gpiod_line_release(gpio_6_line);
        gpiod_line_release(gpio_13_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_6_line, "gpio_6", 0) < 0) {
        perror("Error requesting GPIO 6 as output");
        gpiod_line_release(gpio_5_line);
        gpiod_line_release(gpio_6_line);
        gpiod_line_release(gpio_13_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_13_line, "gpio_13", 0) < 0) {
        perror("Error requesting GPIO 13 as output");
        gpiod_line_release(gpio_5_line);
        gpiod_line_release(gpio_6_line);
        gpiod_line_release(gpio_13_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Set GPIO value
int gpio_set_value(int gpio, int value) {
    if (gpiod_line_set_value(gpio_5_line, value) < 0) {
        perror("Error setting GPIO 5 value");
        return -1;
    }
    if (gpiod_line_set_value(gpio_6_line, value) < 0) {
        perror("Error setting GPIO 6 value");
        return -1;
    }
    if (gpiod_line_set_value(gpio_13_line, value) < 0) {
        perror("Error setting GPIO 13 value");
        return -1;
    }
    return 0;
}

// Get GPIO value
int gpio_get_value(int gpio) {
    int value = gpiod_line_get_value(gpio_5_line);
    if (value < 0) {
        perror("Error getting GPIO 5 value");
        return -1;
    }
    value |= (gpiod_line_get_value(gpio_6_line) << 1);
    if (value < 0) {
        perror("Error getting GPIO 6 value");
        return -1;
    }
    value |= (gpiod_line_get_value(gpio_13_line) << 2);
    if (value < 0) {
        perror("Error getting GPIO 13 value");
        return -1;
    }
    return value;
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set GPIO values
    if (gpio_set_value(GPIO_5, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO 5 value. Exiting.\n");
        cleanup(0);
        return 1;
    }
    if (gpio_set_value(GPIO_6, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO 6 value. Exiting.\n");
        cleanup(0);
        return 1;
    }
    if (gpio_set_value(GPIO_13, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO 13 value. Exiting.\n");
        cleanup(0);
        return 1;
    }

    // Get and print GPIO values
    int value = gpio_get_value(GPIO_5);
    if (value < 0) {
        fprintf(stderr, "Failed to get GPIO 5 value. Exiting.\n");
        cleanup(0);
        return 1;
    }
    printf("GPIO 5: %d\n", value);

    value = gpio_get_value(GPIO_6);
    if (value < 0) {
        fprintf(stderr, "Failed to get GPIO 6 value. Exiting.\n");
        cleanup(0);
        return 1;
    }
    printf("GPIO 6: %d\n", value);

    value = gpio_get_value(GPIO_13);
    if (value < 0) {
        fprintf(stderr, "Failed to get GPIO 13 value. Exiting.\n");
        cleanup(0);
        return 1;
    }
    printf("GPIO 13: %d\n", value);

    // Cleanup and exit
    cleanup(0);

    return 0;
}

