#define MQTT_TOPIC "home/sensor/temperature_humidity"
#define SENSOR_GPIO 4 // Example GPIO pin for sensor
#define SAMPLE_INTERVAL_SEC 5

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor_data(int gpio_pin);
char* format_sensor_data(int sensor_value);
int publish_mqtt_message(const char* topic, const char* message);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        running = 0;
    }
}

// Function to read sensor data from GPIO pin
int read_sensor_data(int gpio_pin) {
    // Simulate reading sensor data (replace with actual sensor reading logic)
    // For example, read an analog value using an ADC connected to the GPIO pin
    // and convert it to a meaningful sensor value.
    // This example returns a random integer between 0 and 100.
    return rand() % 101; // Simulate sensor reading
}

// Function to format sensor data into a string
char* format_sensor_data(int sensor_value) {
    char* timestamp = ctime(&timestamp_t);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove trailing newline
    char* formatted_data = (char*)malloc(100 * sizeof(char)); // Allocate memory for the formatted string
    if (formatted_data == NULL) {
        perror("Failed to allocate memory for formatted data");
        return NULL;
    }
    sprintf(formatted_data, "%s, Sensor Value: %d", timestamp, sensor_value);
    return formatted_data;
}

// Function to publish MQTT message
int publish_mqtt_message(const char* topic, const char* message) {
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(message), message, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin mode (optional, depending on sensor)
    gpioSetMode(SENSOR_GPIO, PI_INPUT); // Set GPIO as input

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor data
        int sensor_value = read_sensor_data(SENSOR_GPIO);

        // Format sensor data
        char* formatted_data = format_sensor_data(sensor_value);
        if (formatted_data == NULL) {
            fprintf(stderr, "Failed to format sensor data\n");
            continue; // Skip to the next iteration
        }

        // Publish MQTT message
        if (publish_mqtt_message(MQTT_TOPIC, formatted_data) != 0) {
            fprintf(stderr, "Failed to publish MQTT message\n");
        }

        free(formatted_data); // Free allocated memory

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Disconnect from MQTT broker
    mosquitto_disconnect(mosq);

    // Disconnect from MQTT broker
    mosquitto_destroy(mosq);

    // Clean up MQTT library
    mosquitto_lib_cleanup();

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

