#include <string.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_BUFFER_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3)

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    unsigned char *buffer = NULL;
    FILE *fp = NULL;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24; // Use RGB24 format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Allocate memory for the image buffer
    buffer = (unsigned char *)malloc(IMAGE_BUFFER_SIZE);
    if (buffer == NULL) {
        perror("Error allocating buffer");
        close(fd);
        return 1;
    }

    // Capture the image
    if (read(fd, buffer, IMAGE_BUFFER_SIZE) < 0) {
        perror("Error reading image");
        free(buffer);
        close(fd);
        return 1;
    }

    // Save the image to a file
    fp = fopen("captured_image.rgb", "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        free(buffer);
        close(fd);
        return 1;
    }

    size_t bytes_written = fwrite(buffer, 1, IMAGE_BUFFER_SIZE, fp);
    if (bytes_written != IMAGE_BUFFER_SIZE) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, IMAGE_BUFFER_SIZE);
        fclose(fp);
        free(buffer);
        close(fd);
        return 1;
    }

    fclose(fp);

    // Clean up
    free(buffer);
    close(fd);

    printf("Image captured and saved to captured_image.rgb\n");

    return 0;
}

