void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[MAX_TIMINGS];
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30
    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100ms
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1); // Wait 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100ms
    }

    // Wait for the DHT22 to pull the line low again
    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100ms
    }

    // Read the 40 bits of data
    for (i = 0; i < MAX_TIMINGS; i++) {
        pulse_counts[i] = 0;
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1); // Wait 1ms
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100ms
        }

        int start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1); // Wait 1ms
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100ms
        }
        int end = gpioTick();
        pulse_counts[i] = end - start;
    }

    // Decode the data
    for (i = 0; i < 40; i++) {
        int index = i / 8;
        int bit = i % 8;
        if (pulse_counts[2 * index + 1] > pulse_counts[2 * index + 3]) {
            data[index] |= (1 << bit);
        }
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum failure\n");
        return -2;
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

