    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio_pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    lines[gpio_pin - GPIO_17] = line; // Store the line for cleanup
    return 0;
}

// Function to set the state of a GPIO line
int set_gpio_state(int gpio_pin, int value) {
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        return -1;
    }

    if (!lines[gpio_pin - GPIO_17]) {
        fprintf(stderr, "Error: GPIO %d not initialized.\n", gpio_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(lines[gpio_pin - GPIO_17], value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d value to %d: %s\n", gpio_pin, value, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup() {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

