// Define GPIO pins
#define GPIO_4 4
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_7 7
#define GPIO_8 8
#define GPIO_9 9

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set GPIO pin state
void set_gpio_state(int gpio, int state) {
    gpioWrite(gpio, state);
    printf("GPIO %d set to %d\n", gpio, state);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
    printf("GPIO %d PWM duty cycle set to %d\n", gpio, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_5, PI_OUTPUT);
    gpioSetMode(GPIO_6, PI_OUTPUT);
    gpioSetMode(GPIO_7, PI_OUTPUT);
    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_4, 255);
    gpioSetPWMrange(GPIO_5, 255);
    gpioSetPWMrange(GPIO_6, 255);
    gpioSetPWMrange(GPIO_7, 255);
    gpioSetPWMrange(GPIO_8, 255);
    gpioSetPWMrange(GPIO_9, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(GPIO_4, 1000);
    gpioSetPWMfrequency(GPIO_5, 1000);
    gpioSetPWMfrequency(GPIO_6, 1000);
    gpioSetPWMfrequency(GPIO_7, 1000);
    gpioSetPWMfrequency(GPIO_8, 1000);
    gpioSetPWMfrequency(GPIO_9, 1000);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set GPIO states and PWM duty cycles
        set_gpio_state(GPIO_4, 1);
        set_pwm_duty_cycle(GPIO_4, 128);

        set_gpio_state(GPIO_5, 0);
        set_pwm_duty_cycle(GPIO_5, 191);

        set_gpio_state(GPIO_6, 1);
        set_pwm_duty_cycle(GPIO_6, 64);

        set_gpio_state(GPIO_7, 0);
        set_pwm_duty_cycle(GPIO_7, 191);

        set_gpio_state(GPIO_8, 1);
        set_pwm_duty_cycle(GPIO_8, 128);

        set_gpio_state(GPIO_9, 0);
        set_pwm_duty_cycle(GPIO_9, 64);

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
