// Define GPIO pins
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18

// Define GPIO chip name (adjust if necessary)
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line17, *line18;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
void cleanup(int signum);

// Signal handler for Ctrl+C
void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip for unexport");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line for unexport");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the direction of a GPIO pin
int gpio_set_direction(int pin, const char *direction) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip for direction setting");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line for direction setting");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for direction setting");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set direction (output)
    ret = gpiod_line_set_value(line, 0); // Set to low initially
    if (ret < 0) {
        perror("Error setting GPIO direction");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to write a value to a GPIO pin
int gpio_write(int pin, int value) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip for writing");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line for writing");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error writing to GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Export GPIO pins
    if (gpio_export(GPIO_PIN_17) < 0) return 1;
    if (gpio_export(GPIO_PIN_18) < 0) {
        gpio_unexport(GPIO_PIN_17);
        return 1;
    }

    // Set GPIO pins as output
    if (gpio_set_direction(GPIO_PIN_17, "out") < 0) {
        gpio_unexport(GPIO_PIN_17);
        gpio_unexport(GPIO_PIN_18);
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN_18, "out") < 0) {
        gpio_unexport(GPIO_PIN_17);
        gpio_unexport(GPIO_PIN_18);
        return 1;
    }

    // Perform 3 cycles
    for (int i = 0; i < 3; i++) {
        // Set GPIO 17 HIGH
        if (gpio_write(GPIO_PIN_17, 1) < 0) {
            gpio_unexport(GPIO_PIN_17);
            gpio_unexport(GPIO_PIN_18);
            return 1;
        }
        // Set GPIO 18 LOW
        if (gpio_write(GPIO_PIN_18, 0) < 0) {
            gpio_unexport(GPIO_PIN_17);
            gpio_unexport(GPIO_PIN_18);
            return 1;
        }

        // Set GPIO 17 LOW
        if (gpio_write(GPIO_PIN_17, 0) < 0) {
            gpio_unexport(GPIO_PIN_17);
            gpio_unexport(GPIO_PIN_18);
            return 1;
        }
        // Set GPIO 18 HIGH
        if (gpio_write(GPIO_PIN_18, 1) < 0) {
            gpio_unexport(GPIO_PIN_17);
            gpio_unexport(GPIO_PIN_18);
            return 1;
        }

        printf("Cycle %d complete\n", i + 1);
    }

    // Unexport GPIO pins
    gpio_unexport(GPIO_PIN_17);
    gpio_unexport(GPIO_PIN_18);

    return 0;
}

