// PCF8574 I2C address
#define PCF8574_ADDR 0x20

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Function to write a byte to the PCF8574
int pcf8574_write(int fd, unsigned char data) {
    unsigned char buf[2];
    buf[0] = 0x40 | (data & 0x07); // Control byte: start bit, single-ended mode, lower 3 bits of data
    buf[1] = (data >> 3) & 0xFF;      // Upper 8 bits of data

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to display a value on the PCF8574
void display_value(int fd, int value) {
    if (value < 0 || value > 9) {
        fprintf(stderr, "Error: Value out of range (0-9)\n");
        return;
    }

    // Clear the display
    pcf8574_write(fd, 0x00);

    // Display the value
    pcf8574_write(fd, value);
}

int main() {
    int fd;

    // Open the I2C device
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the slave address
    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 10; i++) {
            display_value(fd, i);
            usleep(500000); // 0.5 seconds
        }
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(fd);

    return 0;
}

