        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Release chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set GPIO output value
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value to %d: %s\n", line->line, value, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to report GPIO state
int report_gpio_state(int gpio) {
    struct gpiod_line *line = NULL;
    for (int i = 0; i < 6; i++) {
        if (lines[i] && lines[i]->line == gpio) {
            line = lines[i];
            break;
        }
    }

    if (!line) {
        fprintf(stderr, "Error: GPIO %d not found\n", gpio);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d value: %s\n", gpio, strerror(-value));
        return -1;
    }

    printf("GPIO %d: %s\n", gpio, value ? "HIGH" : "LOW");
    return 0;
}

