#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define timeout in microseconds
#define TIMEOUT 50000 // 50ms

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    // Wait for the echo pin to go high (start of the pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Check every 1us
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (end of the pulse)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Check every 1us
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick / 2.0 / 1000000.0 * 34300.0; // Speed of sound: 343 m/s

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stdout, "HC-SR04 sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the distance
        float distance = measureDistance();

        // Check for errors
        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        } else {
            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stdout, "HC-SR04 sensor interface terminated.\n");

    return 0;
}

