#define CAPTURE_DELAY_US 100000 // 0.1 seconds

// Function to initialize the camera device
int init_camera(int *fd) {
    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd == -1) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(*fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(*fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(*fd);
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(int fd, unsigned char **image_data, size_t *image_size) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        return -1;
    }

    *image_size = buf.length;
    *image_data = (unsigned char *)malloc(*image_size);
    if (*image_data == NULL) {
        perror("Error allocating memory for image data");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        free(*image_data);
        *image_data = NULL;
        *image_size = 0;
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        perror("Error during select");
        free(*image_data);
        *image_data = NULL;
        *image_size = 0;
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        free(*image_data);
        *image_data = NULL;
        *image_size = 0;
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        free(*image_data);
        *image_data = NULL;
        *image_size = 0;
        return -1;
    }

    return 0;
}

// Function to save the image to a file
int save_image(const unsigned char *image_data, size_t image_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(image_data, 1, image_size, fp);
    if (bytes_written != image_size) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to release the camera device
void release_camera(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    int fd;
    unsigned char *image_data = NULL;
    size_t image_size = 0;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;

    if (init_camera(&fd) == -1) {
        return EXIT_FAILURE;
    }

    while (1) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.yuv", timeinfo);

        if (capture_image(fd, &image_data, &image_size) == 0) {
            if (save_image(image_data, image_size, filename) == 0) {
                printf("Saved image: %s\n", filename);
            } else {
                fprintf(stderr, "Error saving image\n");
            }
        } else {
            fprintf(stderr, "Error capturing image\n");
        }

        usleep(CAPTURE_DELAY_US);
    }

    release_camera(fd);
    return EXIT_SUCCESS;
}

