#define PCF8574_PORT 0x00

int main() {
    int file;
    int i;

    // Open I2C bus
    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Initialize PCF8574 (set all outputs low)
    unsigned char init_data[2] = {0x00, 0x00};
    if (write(file, init_data, 2) != 2) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    // Display some values
    for (i = 0; i < 16; i++) {
        unsigned char data[2] = {PCF8574_PORT, i};
        if (write(file, data, 2) != 2) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        printf("Displayed: %d\n", i);
        usleep(100000); // Delay for 100ms
    }

    // Close I2C bus
    close(file);

    return 0;
}

