#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulse() {
    long startTime = 0, endTime = 0;
    long pulseDuration = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1; // Timeout
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1; // Timeout
    }

    endTime = gpioTick();

    pulseDuration = endTime - startTime;
    return pulseDuration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    if (pulseDuration < 0) return -1.0; // Indicate error
    return (float)pulseDuration * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance
}

// Function to report the distance
void reportDistance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse duration
        long pulseDuration = measurePulse();

        // Calculate the distance
        float distance = calculateDistance(pulseDuration);

        // Report the distance
        if (distance >= 0) {
            reportDistance(distance);
        } else {
            fprintf(stderr, "Error: Invalid pulse duration.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

