#define I2C_BUS "/dev/i2c-1"
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void int_handler(int dummy) {
    keep_running = 0;
}

int read_sht31(int fd, float *temperature, float *humidity) {
    uint8_t buf[6];
    uint16_t temp_raw, hum_raw;

    // Send measurement command
    buf[0] = (MEASURE_CMD >> 8) & 0xFF;
    buf[1] = MEASURE_CMD & 0xFF;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement (adjust as needed, SHT31 needs ~10ms)
    usleep(20000); // 20ms

    // Read 6 bytes of data
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Convert data
    temp_raw = (buf[0] << 8) | buf[1];
    hum_raw = (buf[3] << 8) | buf[4];

    // Calculate temperature (Celsius)
    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);

    // Calculate humidity (%RH)
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    float temperature, humidity;
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;  // 5 seconds
    sleep_time.tv_nsec = 0;

    // Set up signal handler
    signal(SIGINT, int_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        close(i2c_fd);
        return 1;
    }

    printf("SHT31 Reader\n");

    while (keep_running) {
        if (read_sht31(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SHT31 data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus
    close(i2c_fd);

    printf("Exiting cleanly.\n");
    return 0;
}

