// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (gpio2_line) {
        gpiod_line_release(gpio2_line);
    }
    if (gpio3_line) {
        gpiod_line_release(gpio3_line);
    }
