}

// Initialize GPIO lines
int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio2_line = gpiod_chip_get_line(chip, GPIO_2);
    gpio3_line = gpiod_chip_get_line(chip, GPIO_3);
    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);

    if (!gpio2_line || !gpio3_line || !gpio17_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio2_line, "gpio2", 0) < 0 ||
        gpiod_line_request_output(gpio3_line, "gpio3", 0) < 0 ||
        gpiod_line_request_output(gpio17_line, "gpio17", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Set GPIO value
int gpio_set_value(int gpio, int value) {
    if (gpiod_line_set_value(gpio2_line, value) < 0) {
        perror("Error setting GPIO 2 value");
        return -1;
    }
    if (gpiod_line_set_value(gpio3_line, value) < 0) {
        perror("Error setting GPIO 3 value");
        return -1;
    }
    if (gpiod_line_set_value(gpio17_line, value) < 0) {
        perror("Error setting GPIO 17 value");
        return -1;
    }
    return 0;
}

// Get GPIO value
int gpio_get_value(int gpio) {
    int value;
    if (gpiod_line_get_value(gpio2_line, &value) < 0) {
        perror("Error getting GPIO 2 value");
        return -1;
    }
    if (gpiod_line_get_value(gpio3_line, &value) < 0) {
        perror("Error getting GPIO 3 value");
        return -1;
    }
    if (gpiod_line_get_value(gpio17_line, &value) < 0) {
        perror("Error getting GPIO 17 value");
        return -1;
    }
    return value;
}

