    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Perform 3 cycles
    for (int i = 0; i < 3; i++) {
        // Set GPIO high
