#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <string.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_BUFFER_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3)
#define IMAGE_FILENAME "captured_image.yuv"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    unsigned char *buffer;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    buffer = (unsigned char *)malloc(IMAGE_BUFFER_SIZE);
    if (buffer == NULL) {
        perror("Error allocating buffer");
        close(fd);
        return 1;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device for capture");
        free(buffer);
        return 1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        free(buffer);
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        free(buffer);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        close(fd);
        free(buffer);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Error starting stream");
        close(fd);
        free(buffer);
        return 1;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device for reading");
        close(fd);
        free(buffer);
        return 1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeueing buffer");
        close(fd);
        free(buffer);
        return 1;
    }

    FILE *fp = fopen(IMAGE_FILENAME, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        close(fd);
        free(buffer);
        return 1;
    }

    fwrite(buffer, 1, IMAGE_BUFFER_SIZE, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        perror("Error stopping stream");
        close(fd);
        free(buffer);
        return 1;
    }

    close(fd);
    free(buffer);

    printf("Image captured and saved to %s\n", IMAGE_FILENAME);
    return 0;
}

