        return -1;
    }

    bytes_read = read(fd, line, sizeof(line) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %s: %s\n", w1_slave_path, strerror(errno));
        close(fd);
        return -1;
    }
    line[bytes_read] = '\0';
    close(fd);

    // Check for CRC error
    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device %s\n", device_id);
        return -1;
    }

    // Extract temperature
    snprintf(temp_path, sizeof(temp_path), "%s/%s", W1_DEVICES_DIR, device_id);
    snprintf(temp_path, sizeof(temp_path), "%s/%s", temp_path, W1_TEMP_FILE);

    fd = open(temp_path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", temp_path, strerror(errno));
        return -1;
    }

    bytes_read = read(fd, temp_str, sizeof(temp_str) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %s: %s\n", temp_path, strerror(errno));
        close(fd);
        return -1;
    }
    temp_str[bytes_read] = '\0';
    close(fd);

    token = strstr(temp_str, "t=");
    if (token == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", temp_path);
        return -1;
    }

    token += 2; // Move pointer past "t="
    temp_int = strtol(token, NULL, 10);

    *temperature = (float)temp_int / 1000.0;

