    int rc;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 2 as an output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("GPIO %d control program started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate) {
        /* Set GPIO 2 HIGH */
        rc = gpioWrite(GPIO_PIN, 1);
        if (rc != 0) {
            fprintf(stderr, "Error writing HIGH to GPIO %d: %d\n", GPIO_PIN, rc);
