            gpioTerminate();
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio re-initialisation failed\n");
                break; /* Exit loop if re-initialization fails */
            }
            continue; /* Skip to the next iteration */
        }

        /* Print the state of GPIO 2 */
        printf("GPIO %d is HIGH\n", GPIO_PIN);

        /* Wait for 5 seconds */
        sleep(5);

        /* Set GPIO 2 LOW */
        rc = gpioWrite(GPIO_PIN, 0);
        if (rc != 0) {
            fprintf(stderr, "Error writing LOW to GPIO %d: %d\n", GPIO_PIN, rc);
            /* Attempt to recover by re-initializing pigpio */
            gpioTerminate();
            if (gpioInitialise() < 0) {
