#define DHT22_GPIO 4
#define MAX_RETRIES 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    int i, j;
    long start_time, end_time;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30 us
    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100 us
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100 us
    }

    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100 us
    }

    // Read the 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100 us
        }

        start_time = time_time();

        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100 us
        }

        end_time = time_time();

        pulse_count++;
        if ((end_time - start_time) > 0.0000005) { // 5 us
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate the checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum failure\n");
        return -2;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    for (int cycle = 0; cycle < MAX_RETRIES && !terminate; cycle++) {
        result = read_dht22(DHT22_GPIO, &temperature, &humidity);
        if (result == 0) {
            printf("Cycle %d: Temperature = %.1f\u00b0C, Humidity = %.1f%%\n", cycle + 1, temperature, humidity);
        } else {
            fprintf(stderr, "Cycle %d: DHT22 read failed (error code %d)\n", cycle + 1, result);
        }
        if (result != 0) break; // Exit loop if read fails
    }

    gpioTerminate();
    return 0;
}

