#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_TIMINGS 85

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    int data_bits[MAX_TIMINGS] = {0};
    int last_state = PI_HIGH;
    int current_state;
    int i;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(30); // Modified delay to 30 us
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == PI_HIGH) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22: Timeout waiting for start signal\n");
            return data; // Return invalid data
        }
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == PI_LOW) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22: Timeout waiting for end of start signal\n");
            return data; // Return invalid data
        }
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == PI_HIGH) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22: Timeout waiting for data signal\n");
            return data; // Return invalid data
        }
    }

    // Read 40 bits of data
    for (i = 0; i < MAX_TIMINGS; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == PI_LOW) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22: Timeout waiting for rising edge\n");
                return data; // Return invalid data
            }
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == PI_HIGH) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22: Timeout waiting for falling edge\n");
                return data; // Return invalid data
            }
        }

        data_bits[i] = gpioRead(DHT22_GPIO);
    }

    // Decode the data
    int humidity_int = 0;
    int humidity_frac = 0;
    int temperature_int = 0;
    int temperature_frac = 0;

    for (i = 0; i < 16; i++) {
        if (data_bits[i * 2] == PI_LOW && data_bits[i * 2 + 1] == PI_HIGH) {
            humidity_int |= (1 << (15 - i));
        }
    }

    for (i = 16; i < 32; i++) {
        if (data_bits[i * 2] == PI_LOW && data_bits[i * 2 + 1] == PI_HIGH) {
            humidity_frac |= (1 << (31 - i));
        }
    }

    for (i = 32; i < 48; i++) {
        if (data_bits[i * 2] == PI_LOW && data_bits[i * 2 + 1] == PI_HIGH) {
            temperature_int |= (1 << (47 - i));
        }
    }

    for (i = 48; i < 64; i++) {
        if (data_bits[i * 2] == PI_LOW && data_bits[i * 2 + 1] == PI_HIGH) {
            temperature_frac |= (1 << (63 - i));
        }
    }

    data.humidity = (float)humidity_int + (float)humidity_frac / 10.0;
    data.temperature = (float)temperature_int + (float)temperature_frac / 10.0;
    data.valid = 1; // Assume valid until proven otherwise

    // Validate the data
    if (data.temperature < -40.0 || data.temperature > 80.0 || data.humidity < 0.0 || data.humidity > 100.0) {
        fprintf(stderr, "DHT22: Invalid data received\n");
        data.valid = 0;
    }

    return data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    for (int i = 0; i < 3; i++) {
        DHT22Data dht22_data = read_dht22();

        if (dht22_data.valid) {
            printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", dht22_data.temperature, dht22_data.humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 data after multiple retries.\n");
        }

        sleep(60);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

#include <stdio.h>
