#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *lines[5];

// Function prototypes
int setup_gpio(int gpio);
int cleanup_gpio(int gpio);
void cycle_gpio(int gpio, int value);
void report_state(int gpio, int value);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(GPIO_8);
    cleanup_gpio(GPIO_9);
    cleanup_gpio(GPIO_10);
    cleanup_gpio(GPIO_11);
    cleanup_gpio(GPIO_23);
    gpiod_chip_close(chip);
    exit(0);
}

// Setup GPIO line
int setup_gpio(int gpio) {
    char line_str[3];
    snprintf(line_str, sizeof(line_str), "%d", gpio);

    lines[gpio - GPIO_8] = gpiod_chip_get_line(chip, line_str);
    if (!lines[gpio - GPIO_8]) {
        perror("Error getting GPIO line");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(lines[gpio - GPIO_8], &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        return -1;
    }

    return 0;
}

// Cleanup GPIO line
int cleanup_gpio(int gpio) {
    if (!lines[gpio - GPIO_8]) {
        return 0; // Nothing to cleanup
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT; // Release the line

    int ret = gpiod_line_request(lines[gpio - GPIO_8], &config, 0);
    if (ret < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }

    return 0;
}

// Cycle GPIO line
void cycle_gpio(int gpio, int value) {
    int ret = gpiod_line_set_value(lines[gpio - GPIO_8], value);
    if (ret < 0) {
        perror("Error setting GPIO value");
    }
}

// Report GPIO state
void report_state(int gpio, int value) {
    printf("GPIO %d: %s\n", gpio, value ? "HIGH" : "LOW");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(GPIO_8) < 0 ||
        setup_gpio(GPIO_9) < 0 ||
        setup_gpio(GPIO_10) < 0 ||
        setup_gpio(GPIO_11) < 0 ||
        setup_gpio(GPIO_23) < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Perform 3 cycles
    for (int i = 0; i < 3; i++) {
        // Cycle GPIO 8
        cycle_gpio(GPIO_8, 1);
        report_state(GPIO_8, 1);
        usleep(500000); // 0.5 seconds
        cycle_gpio(GPIO_8, 0);
        report_state(GPIO_8, 0);
        usleep(500000); // 0.5 seconds

        // Cycle GPIO 9
