        // Cycle GPIO 11
        cycle_gpio(GPIO_11, 1);
        report_state(GPIO_11, 1);
        usleep(500000); // 0.5 seconds
        cycle_gpio(GPIO_11, 0);
        report_state(GPIO_11, 0);
        usleep(500000); // 0.5 seconds

        // Cycle GPIO 23
        cycle_gpio(GPIO_23, 1);
        report_state(GPIO_23, 1);
        usleep(500000); // 0.5 seconds
        cycle_gpio(GPIO_23, 0);
        report_state(GPIO_23, 0);
        usleep(500000); // 0.5 seconds
    }

    // Cleanup GPIO lines
    cleanup_gpio(GPIO_8);
    cleanup_gpio(GPIO_9);
    cleanup_gpio(GPIO_10);
    cleanup_gpio(GPIO_11);
    cleanup_gpio(GPIO_23);

    // Close GPIO chip
    gpiod_chip_close(chip);

