#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *lines[4];

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Release chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit program
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    lines[0] = gpiod_chip_get_line(chip, GPIO_17);
    lines[1] = gpiod_chip_get_line(chip, GPIO_22);
    lines[2] = gpiod_chip_get_line(chip, GPIO_23);
    lines[3] = gpiod_chip_get_line(chip, GPIO_27);

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            perror("Error requesting GPIO line for output");
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Toggle GPIO states
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_get_value(lines[i]) == 0) {
                gpiod_line_set_value(lines[i], 1);
            } else {
                gpiod_line_set_value(lines[i], 0);
            }
        }

        // Print current GPIO states
        for (int i = 0; i < 4; i++) {
            int value = gpiod_line_get_value(lines[i]);
            printf("GPIO %d: %s\n", GPIO_17 + i, value ? "HIGH" : "LOW");
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    return 0;
}

