        perror("Failed to get SPI mode");
        close(fd);
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return 1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD) < 0) {
        perror("Failed to get bits per word");
        close(fd);
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Failed to set max speed hz");
        close(fd);
        return 1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ) < 0) {
        perror("Failed to get max speed hz");
        close(fd);
        return 1;
    }

    while (keep_running) {
        ret = spi_read(fd, data, 4);
        if (ret < 0) {
            fprintf(stderr, "SPI read failed. Exiting.\n");
            break;
        }

        // Check for fault bit
        if (data[3] & 0x01) {
            fprintf(stderr, "MAX31855 Fault detected!\n");
            fprintf(stderr, "Fault code: %d\n", data[3] & 0x07);
            close(fd);
            return 1;
        }

        // Extract temperature
        int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
        float temperature = raw_temp * 0.25;

        // Extract internal temperature
        int16_t raw_int_temp = ((data[2] << 8) | data[3]) >> 4;
        float internal_temperature = raw_int_temp * 0.0625;

        // Extract fault status
        int fault_status = data[3] & 0x07;

        printf("Temperature: %.2f °C, Internal Temp: %.2f °C, Fault: %d\n", temperature, internal_temperature, fault_status);
        sleep(1);
    }

    close(fd);
    return 0;
