#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define LOAD_PIN 18
#define GROUND_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float measureDistance() {
    long long start_tick, end_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for the echo pin to go high (or timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (or timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    // Calculate the pulse duration in microseconds
    long long pulse_duration = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to load the sensor
void loadSensor() {
    gpioWrite(LOAD_PIN, 1);
    gpioDelay(10); // Load time
    gpioWrite(LOAD_PIN, 0);
}

// Function to ground the sensor
void groundSensor() {
    gpioWrite(GROUND_PIN, 1);
    gpioDelay(10); // Ground time
    gpioWrite(GROUND_PIN, 0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LOAD_PIN, PI_OUTPUT);
    gpioSetMode(GROUND_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Set ground pin low initially
    gpioWrite(GROUND_PIN, 0);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 sensor interface program\n");

    // Main loop
    while (program_running) {
        // Load the sensor
        loadSensor();

        // Ground the sensor
        groundSensor();

        // Measure the distance
        float distance = measureDistance();

        // Print the distance
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

