int i2c_write_byte(int file_descriptor, uint8_t reg_address, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg_address;
    buffer[1] = value;
    if (write(file_descriptor, buffer, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

