// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04
#define VEML7700_WHITE_DATA 0x05

// Configuration values
#define ALS_IT_800MS 0x00  // Integration time: 800ms
#define ALS_GAIN_1_8 0x00  // Gain: 1/8
#define ALS_POWER_ON 0x02  // Power on ALS

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program.\n");
    close(i2c_fd);
    exit(0);
}

// Function to write a byte to a VEML7700 register
int veml7700_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VEML7700 register
int veml7700_read_reg(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure VEML7700
    if (veml7700_write_reg(i2c_fd, VEML7700_CONFIG, ALS_IT_800MS | ALS_GAIN_1_8 | ALS_POWER_ON) < 0) {
        fprintf(stderr, "Failed to configure VEML7700\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t als_data, white_data;

    // Main loop
    while (1) {
        // Read ALS data
        if (veml7700_read_reg(i2c_fd, VEML7700_ALS_DATA, &als_data) < 0) {
            fprintf(stderr, "Failed to read ALS data\n");
            close(i2c_fd);
            return 1;
        }

        // Read white data
        if (veml7700_read_reg(i2c_fd, VEML7700_WHITE_DATA, &white_data) < 0) {
            fprintf(stderr, "Failed to read white data\n");
            close(i2c_fd);
            return 1;
        }

        // Print the readings
        printf("ALS: %u, White: %u\n", als_data, white_data);

        // Wait 0.5 seconds
        sleep(0.5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define MAX_BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred, no data available
            return 0;
        }
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    char buffer[MAX_BUFFER_SIZE];
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 0.1 seconds

    printf("UART communication started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }
        nanosleep(&sleep_time, NULL);
    }

    close(uart_fd);
    printf("UART port closed. Exiting.\n");
    return EXIT_SUCCESS;
}

