        return -1;
    }

    gpioSetMode(config.trigger_pin, PI_OUTPUT);
    gpioSetMode(config.echo_pin, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(config.trigger_pin, 0);
    gpioDelay(1000); // 1ms

    return 0;
}

// Sends a 10us pulse to the trigger pin
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measures the pulse width on the echo pin
long measure_pulse_width() {
    long start_time = 0, end_time = 0;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1us
    }
    if (count >= TIMEOUT_US) return -1; // Timeout

    start_time = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1us
    }
    if (count >= TIMEOUT_US) return -1; // Timeout

    end_time = gpioTick();

    return end_time - start_time;
}

// Calculates the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Reports the distance to standard output
void report_distance(float distance) {
    if (distance < 0) {
        fprintf(stderr, "Invalid distance reading\n");
    } else if (distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

// Cleans up the GPIO pins and terminates the pigpio library
void cleanup_gpio(gpio_config_t config) {
    gpioTerminate();
}

int main() {
    gpio_config_t gpio_config = {TRIGGER_PIN, ECHO_PIN};

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(gpio_config) != 0) {
        return 1;
    }

    printf("HC-SR04 sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            report_distance(distance);
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        gpioDelay(500000); // 0.5 seconds
    }

    // Clean up GPIO
    cleanup_gpio(gpio_config);

    return 0;
}

