#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

int main() {
    int fd;
    int addr = ADXL345_ADDR;
    int data;
    char buf[1];

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Specify slave address
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        exit(1);
    }

    // Initialize ADXL345
    buf[0] = POWER_CTL;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to POWER_CTL register");
        close(fd);
        exit(1);
    }
    buf[0] = 0x08; // Enable measurement mode
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to POWER_CTL register");
        close(fd);
        exit(1);
    }

    buf[0] = DATA_FORMAT;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to DATA_FORMAT register");
        close(fd);
        exit(1);
    }
    buf[0] = 0x08; // +/- 2g range, full resolution
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to DATA_FORMAT register");
        close(fd);
        exit(1);
    }

    // Read X, Y, and Z axis data
    buf[0] = DATAX0;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to DATAX0 register");
        close(fd);
        exit(1);
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read DATAX0 register");
        close(fd);
        exit(1);
    }
    data = buf[0];

    buf[0] = DATAX1;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to DATAX1 register");
        close(fd);
        exit(1);
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read DATAX1 register");
        close(fd);
        exit(1);
    }
    data |= (buf[0] << 8);

    buf[0] = DATAY0;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to DATAY0 register");
        close(fd);
        exit(1);
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read DATAY0 register");
        close(fd);
        exit(1);
    }
    data |= (buf[0] << 8);

    buf[0] = DATAY1;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to DATAY1 register");
        close(fd);
        exit(1);
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read DATAY1 register");
        close(fd);
        exit(1);
    }
    data |= (buf[0] << 8);

    buf[0] = DATAZ0;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to DATAZ0 register");
        close(fd);
        exit(1);
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read DATAZ0 register");
        close(fd);
        exit(1);
    }
    data |= (buf[0] << 8);

    buf[0] = DATAZ1;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to DATAZ1 register");
        close(fd);
        exit(1);
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read DATAZ1 register");
        close(fd);
        exit(1);
    }
    data |= (buf[0] << 8);

    // Print the data
    printf("X: %d, Y: %d, Z: %d\n", data, data >> 8, data);

    // Close I2C bus
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25
#define GPIO_27 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, state == 1 ? "HIGH" : "LOW");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    int gpios[] = {GPIO_4, GPIO_17, GPIO_18, GPIO_22, GPIO_23, GPIO_24, GPIO_25, GPIO_27};
    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); ++i) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", gpios[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Set GPIO states
        set_gpio_state(GPIO_4, 1);
        set_gpio_state(GPIO_17, 1);
        set_gpio_state(GPIO_18, 1);
        set_gpio_state(GPIO_22, 1);
        set_gpio_state(GPIO_23, 1);
        set_gpio_state(GPIO_24, 1);
        set_gpio_state(GPIO_25, 1);
        set_gpio_state(GPIO_27, 1);

        // Report GPIO states
        report_gpio_state(GPIO_4, 1);
        report_gpio_state(GPIO_17, 1);
        report_gpio_state(GPIO_18, 1);
        report_gpio_state(GPIO_22, 1);
        report_gpio_state(GPIO_23, 1);
        report_gpio_state(GPIO_24, 1);
        report_gpio_state(GPIO_25, 1);
        report_gpio_state(GPIO_27, 1);

        // Wait 0.05 seconds
        usleep(50000); // 0.05 seconds = 50000 microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

