#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;
    int dutycycle;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO 18 as output */
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    /* Set PWM frequency */
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    /* Set PWM range */
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("PWM control on GPIO %d. Press Ctrl+C to exit.\n", PWM_GPIO);

    while (!terminate) {
        /* Generate a random duty cycle (0-1000) */
        dutycycle = rand() % (PWM_RANGE + 1);

