#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int cycles = 5;
    int current_cycle = 0;

    /* Register signal handler for Ctrl+C */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate && current_cycle < cycles) {
        /* Toggle GPIO state */
        int current_state = gpiod_line_get_value(line);
        int new_state = !current_state;
        if (gpiod_line_set_value(line, new_state) < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        /* Report current state */
        printf("GPIO %d is now %d\n", GPIO_PIN, new_state);

        current_cycle++;
        sleep(1); // Wait for 1 second
    }

    /* Release GPIO line */
    if (gpiod_line_release(line) < 0) {
        perror("gpiod_line_release");
    }

    /* Close GPIO chip */
    if (gpiod_chip_close(chip) < 0) {
        perror("gpiod_chip_close");
    }

    printf("GPIO %d control stopped.\n", GPIO_PIN);

    return 0;
}

