#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[4];

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

// Function to initialize a GPIO line
int init_gpio(int gpio, struct gpiod_line **line) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return -1;
    }

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio, CHIP_NAME);
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(*line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", gpio, CHIP_NAME);
        gpiod_line_release(*line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value to %d: %s\n", line->gpio, value, CHIP_NAME);
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup() {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Initialize GPIO lines
    lines[0] = NULL;
    lines[1] = NULL;
    lines[2] = NULL;
    lines[3] = NULL;

    if (init_gpio(GPIO_17, &lines[0]) < 0) return 1;
    if (init_gpio(GPIO_18, &lines[1]) < 0) return 1;
    if (init_gpio(GPIO_22, &lines[2]) < 0) return 1;
    if (init_gpio(GPIO_27, &lines[3]) < 0) return 1;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
