// Function to initialize a GPIO line
int initialize_gpio(int gpio) {
    char line_str[3];
    snprintf(line_str, sizeof(line_str), "%d", gpio);

    struct gpiod_line *line = gpiod_chip_get_line(chip, line_str);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    lines[gpio] = line;

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO line
int set_gpio_state(int gpio, int value) {
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        return -1;
    }

    int ret = gpiod_line_set_value(lines[gpio], value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d value to %d: %s\n", gpio, value, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup() {
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

