#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOAD_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to measure the pulse width on the echo pin
long measurePulseWidth() {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go HIGH
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= 10000) return -1; // Timeout

    startTime = gpioTick();

    // Wait for the echo pin to go LOW
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= 10000) return -1; // Timeout

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (pulseWidth * 0.0343) / 2.0;
}

// Function to load the distance into the load pin
void loadDistance(float distance) {
    if (distance < 0) {
        gpioWrite(LOAD_PIN, 0); // Indicate error
        return;
    }
    gpioWrite(LOAD_PIN, 1); // Load the distance into the load pin
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LOAD_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Distance Measurement Program\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseWidth = measurePulseWidth();
        float distance = calculateDistance(pulseWidth);

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Error: Could not measure distance\n");
        }

        loadDistance(distance);
        gpioDelay(500); // Delay for 500 milliseconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    return 0;
}

