#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define INTERRUPT_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance();
void report_state(double distance);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
    int interrupt_pin;
} gpio_config_t;

// Global GPIO configuration
gpio_config_t gpio_config = {
    .trigger_pin = TRIGGER_PIN,
    .echo_pin = ECHO_PIN,
    .interrupt_pin = INTERRUPT_PIN
};

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(gpio_config.trigger_pin, PI_OUTPUT);
    gpioSetMode(gpio_config.echo_pin, PI_INPUT);
    gpioSetMode(gpio_config.interrupt_pin, PI_INPUT);

    // Set pull-down resistor on interrupt pin
    gpioSetPullUpDown(gpio_config.interrupt_pin, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();
        double distance = calculate_distance();
        report_state(distance);
        gpioDelay(100); // 0.1 second delay
    }

    return 0;
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(gpio_config.trigger_pin, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(gpio_config.trigger_pin, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == gpio_config.echo_pin) {
        if (level == 1) {
            pulse_start = tick;
            timeout_flag = 0; // Reset timeout flag
        } else if (level == 0) {
            pulse_end = tick;
            timeout_flag = 1; // Set timeout flag
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance() {
    if (pulse_start == 0 || pulse_end == 0) {
        return -1.0; // Indicate error
    }

    double pulse_duration = (double)(pulse_end - pulse_start);
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2

    return distance;
}

// Function to report the state (distance or error)
void report_state(double distance) {
    if (distance < 0) {
        printf("Error: No echo received or timeout occurred.\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    gpioTerminate();
    exit(0);
}

