#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29

int i2c_fd;

void signal_handler(int sig);
int tcs34725_init();
int tcs34725_read_data(unsigned int *r, unsigned int *g, unsigned int *b, unsigned int *c);

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    unsigned int r, g, b, c;

    while (1) {
        if (tcs34725_read_data(&r, &g, &b, &c) == 0) {
            printf("R: %u, G: %u, B: %u, C: %u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read data. Retrying.\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    close(i2c_fd);
    exit(0);
}

int tcs34725_init() {
    // Enable the device
    unsigned char buf[2];
    buf[0] = 0x80; // Enable register
    buf[1] = 0x01; // Enable power and ALS

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return 1;
    }

    // Set integration time (ATIME) - 2.4ms * 256
    buf[0] = 0x8F; // ATIME register
    buf[1] = 0xD5; // 2.4ms integration time
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return 1;
    }

    // Set gain (AGAIN) - 4x gain
    buf[0] = 0x81; // AGAIN register
    buf[1] = 0x01; // 4x gain
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return 1;
    }

    return 0;
}

int tcs34725_read_data(unsigned int *r, unsigned int *g, unsigned int *b, unsigned int *c) {
    unsigned char buf[1];
    unsigned char data[8];

    // Read all 8 bytes at once
    buf[0] = 0x14; // First byte of the data register
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return 1;
    }

    if (read(i2c_fd, data, 8) != 8) {
        perror("Error reading from I2C device");
