#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define GROUND_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulse() {
    long startTime = 0, endTime = 0;
    int timeout = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        startTime = gpioTick();
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1; // Indicate timeout
    }

    // Wait for the echo pin to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        endTime = gpioTick();
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1; // Indicate timeout
    }

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    if (pulseDuration < 0) return -1.0; // Indicate error
    return (float)pulseDuration * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and then divide by 2 for one-way distance
}

// Function to report the distance
void reportDistance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(GROUND_PIN, PI_OUTPUT); // Set ground pin as output
    gpioWrite(GROUND_PIN, 0); // Ensure ground is initially low

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        triggerSensor();
        long pulseDuration = measurePulse();
        float distance = calculateDistance(pulseDuration);

        if (distance >= 0) {
            reportDistance(distance);
        } else {
            fprintf(stderr, "Error: Invalid pulse duration.\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

