// Function to initialize a GPIO line
int initialize_gpio(struct gpiod_chip *chip, int gpio) {
    struct gpiod_line *line;
    char line_name[20];

    snprintf(line_name, sizeof(line_name), "gpio%d", gpio);
    line = gpiod_chip_get_line(chip, line_name);
    if (!line) {
