int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line value: %s\n", strerror(errno));
        return -1;
    }
