#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from the MPU6050
int read_byte(int reg) {
    uint8_t buf[1];
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, buf, 1) != 1) {
        perror("Failed to read byte");
        return -1;
    }
    return buf[0];
}

// Function to read a 16-bit word from the MPU6050
int16_t read_word(int reg) {
    uint8_t buf[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read word");
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (read_byte(PWR_MGMT_1) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t accel_x = read_word(ACCEL_XOUT_H);
        int16_t accel_y = read_word(ACCEL_YOUT_H);
        int16_t accel_z = read_word(ACCEL_ZOUT_H);

        // Print the readings
        printf("Accelerometer: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
