#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;

    /* Register signal handler for graceful termination */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request(line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to HIGH\n", GPIO_PIN);

    while (!terminate) {
        /* Set GPIO HIGH */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO HIGH");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        /* Wait 0.6 seconds */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO LOW");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        usleep(600000); // 0.6 seconds
    }

    /* Release GPIO line */
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    /* Close GPIO chip */
    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        perror("Error closing GPIO chip");
    }

    printf("Program terminated gracefully.\n");
    return 0;
}

